def num_matching_subseq(s, words):
    def is_subsequence(word):
        i = 0
        for ch in s:                                             # rescans all of s for every single word
            if i < len(word) and word[i] == ch:
                i += 1
        return i == len(word)

    return sum(1 for word in words if is_subsequence(word))


if __name__ == "__main__":
    print(num_matching_subseq("abcde", ["a", "bb", "acd", "ace"]))

