import java.util.*;

public class Main {
    int numMatchingSubseq(String s, String[] words) {
        int count = 0;
        for (String word : words) {
            int i = 0;
            for (char ch : s.toCharArray()) {                          // rescans all of s for every single word
                if (i < word.length() && word.charAt(i) == ch) i++;
            }
            if (i == word.length()) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.numMatchingSubseq("abcde", new String[]{"a", "bb", "acd", "ace"}));
    }
}

