def num_matching_subseq(s, words):
    waiting = {}                                              # character to list of (word, position) waiting for it
    for word in words:
        first_char = word[0]
        waiting.setdefault(first_char, []).append((word, 0))

    count = 0
    for ch in s:
        current_waiters = waiting.get(ch, [])
        waiting[ch] = []                                            # this bucket is being processed, clear it
        for word, pos in current_waiters:
            pos += 1
            if pos == len(word):
                count += 1                                              # this word has been fully matched
            else:
                next_char = word[pos]
                waiting.setdefault(next_char, []).append((word, pos))     # move to the bucket for its next character
    return count


if __name__ == "__main__":
    print(num_matching_subseq("abcde", ["a", "bb", "acd", "ace"]))

