import java.util.*;

public class Main {
    int numMatchingSubseq(String s, String[] words) {
        Map<Character, List<int[]>> waiting = new HashMap<>();          // maps char to list of [wordIndex, position]
        for (int w = 0; w < words.length; w++) {
            char firstChar = words[w].charAt(0);
            waiting.computeIfAbsent(firstChar, k -> new ArrayList<>()).add(new int[]{w, 0});
        }
        int count = 0;
        for (char ch : s.toCharArray()) {
            List<int[]> currentWaiters = waiting.getOrDefault(ch, new ArrayList<>());
            waiting.put(ch, new ArrayList<>());                             // this bucket is being processed, clear it
            for (int[] pair : currentWaiters) {
                int w = pair[0], pos = pair[1] + 1;
                if (pos == words[w].length()) {
                    count++;                                                     // this word has been fully matched
                } else {
                    char nextChar = words[w].charAt(pos);
                    waiting.computeIfAbsent(nextChar, k -> new ArrayList<>()).add(new int[]{w, pos});  // move to next bucket
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.numMatchingSubseq("abcde", new String[]{"a", "bb", "acd", "ace"}));
    }
}

