#include <bits/stdc++.h>
using namespace std;

int numMatchingSubseq(string s, vector<string>& words) {
    unordered_map<char, vector<pair<int, int>>> waiting;                 // maps char to list of (wordIndex, position)
    for (int w = 0; w < (int)words.size(); w++) {
        waiting[words[w][0]].push_back({w, 0});
    }
    int count = 0;
    for (char ch : s) {
        auto currentWaiters = waiting[ch];
        waiting[ch].clear();                                                // this bucket is being processed, clear it
        for (auto& [w, pos] : currentWaiters) {
            int newPos = pos + 1;
            if (newPos == (int)words[w].size()) {
                count++;                                                        // this word has been fully matched
            } else {
                waiting[words[w][newPos]].push_back({w, newPos});                 // move to the bucket for its next char
            }
        }
    }
    return count;
}

int main() {
    string s = "abcde";
    vector<string> words = {"a", "bb", "acd", "ace"};
    cout << numMatchingSubseq(s, words) << endl;
    return 0;
}
